import { createClient } from 'supabase';
import Papa from 'papaparse';

const REPO='vibedatascience/understat_players_aggregated';
const COMMIT='768b7ca0b977a5e6b4b429c7b0cf750e8269f2fc';
const FILE='understat_players_aggregated_2014_2024.csv';
const BLOB='ddf4327251bb781f88b6edc4662bf20e5379ff3f';
const URL=`https://raw.githubusercontent.com/${REPO}/${COMMIT}/${FILE}`;
const SUPPORTED=new Set(['La_Liga','Bundesliga','Serie_A','Ligue_1']);
const LEAGUE_NAME:Record<string,string>={La_Liga:'La Liga',Bundesliga:'Bundesliga',Serie_A:'Serie A',Ligue_1:'Ligue 1',EPL:'Premier League'};
const clean=(v:any)=>v===undefined||v===null?null:String(v).trim();
const num=(v:any)=>{const s=clean(v);if(s===null||s==='')return null;const n=Number(s);return Number.isFinite(n)?n:null};
const pos=(primary:any,raw:any)=>{const p=(clean(primary)||'').toUpperCase();if(p==='D')return'DEF';if(p==='M')return'MID';if(p==='F')return'FWD';const r=(clean(raw)||'').toUpperCase().replace(/\s+/g,'');if(r.startsWith('D')||r.includes('D'))return'DEF';if(r.startsWith('M')||r.includes('M'))return'MID';if(r.startsWith('F')||r.includes('F'))return'FWD';return null};
const err=(e:any)=>e instanceof Error?e.message:String(e);
const chunks=<T,>(a:T[],n=200)=>{const z:T[][]=[];for(let i=0;i<a.length;i+=n)z.push(a.slice(i,i+n));return z};

Deno.serve(async(req)=>{try{
  if(req.method!=='POST')return Response.json({ok:false,error:'POST required'},{status:405});
  const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');const key=keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');if(!key)throw new Error('Missing service credential');
  const sb=createClient(Deno.env.get('SUPABASE_URL')!,key,{auth:{persistSession:false}});
  const {data:adminToken,error:authError}=await sb.rpc('get_backend_secret',{secret_name:'FOOTBALL_ENGINE_ADMIN_TOKEN'});if(authError||!adminToken||req.headers.get('x-engine-token')!==adminToken)return Response.json({ok:false,error:'unauthorized'},{status:401});
  const body=await req.json().catch(()=>({}));const cohort=String(body.cohort||'').toUpperCase();const dryRun=body.dry_run!==false;
  const cfg=cohort==='VALIDATION'?{sy:2023,dy:2024,sl:'2023-2024',dl:'2024-2025',split:'VALIDATION'}:cohort==='TRAIN'?{sy:2022,dy:2023,sl:'2022-2023',dl:'2023-2024',split:'TRAIN'}:null;
  if(!cfg)return Response.json({ok:false,error:'cohort must be VALIDATION or TRAIN'},{status:400});
  const response=await fetch(URL);if(!response.ok)throw new Error(`archive fetch ${response.status}`);const text=await response.text();
  const parsed=Papa.parse(text,{header:true,skipEmptyLines:true});if(parsed.errors.length>25)throw new Error(`CSV parse errors ${parsed.errors.length}`);const all=parsed.data as any[];
  const byIdYear=new Map<string,any[]>();
  for(const r of all){const id=clean(r.id),year=num(r.year);if(!id||year===null)continue;if(year!==cfg.sy&&year!==cfg.dy)continue;const k=`${id}:${year}`;let a=byIdYear.get(k);if(!a){a=[];byIdYear.set(k,a)}a.push(r)}
  const source:any[]=[];const dest=new Map<string,any>();
  let sourceMulti=0,destMulti=0;
  for(const [k,rows] of byIdYear){const year=Number(k.split(':').pop());if(rows.length!==1){if(year===cfg.sy)sourceMulti++;else if(year===cfg.dy)destMulti++;continue}const r=rows[0];const league=clean(r.league)||'';const mins=num(r.time),xg=num(r.xG),xa=num(r.xA),pg=pos(r.primary_position,r.position),id=String(r.id);
    if(mins===null||mins<450||xg===null||xa===null||!pg)continue;
    if(year===cfg.sy&&SUPPORTED.has(league))source.push({id,r,league,mins,xg,xa,pg});
    if(year===cfg.dy&&league==='EPL')dest.set(id,{id,r,league,mins,xg,xa,pg});
  }
  const pairs:any[]=[];for(const a of source){const b=dest.get(a.id);if(!b)continue;const playerName=clean(b.r.player_name)||clean(a.r.player_name)||`understat:${a.id}`;const sourceClub=clean(a.r.team_title);const destClub=clean(b.r.team_title);if(!sourceClub||!destClub)continue;
    pairs.push({pair_key:`C0206_${cfg.split}_${cfg.sy}_${cfg.dy}_UNDERSTAT_${a.league}_PL_${a.id}`,player_name:playerName,player_identity_key:`understat_player_id:${a.id}`,source_season:cfg.sl,destination_season:cfg.dl,source_competition:LEAGUE_NAME[a.league],destination_competition:'Premier League',source_club:sourceClub,destination_club:destClub,position_group:b.pg||a.pg,source_minutes:Math.round(a.mins),destination_minutes:Math.round(b.mins),source_xg:a.xg,source_xa:a.xa,destination_xg:b.xg,destination_xa:b.xa,
      source_provenance:{metric_source:'Understat aggregate archive',repository:REPO,repository_commit:COMMIT,file:FILE,file_blob_sha:BLOB,understat_player_id:a.id,league_code:a.league,year:cfg.sy,identity_method:'stable Understat player id',season_record_count:1,minutes_field:'time',xg_field:'xG',xa_field:'xA',same_provider_source_destination:true},
      destination_provenance:{metric_source:'Understat aggregate archive',repository:REPO,repository_commit:COMMIT,file:FILE,file_blob_sha:BLOB,understat_player_id:a.id,league_code:'EPL',year:cfg.dy,identity_method:'stable Understat player id',season_record_count:1,minutes_field:'time',xg_field:'xG',xa_field:'xA',same_provider_source_destination:true},
      cohort_split:cfg.split,pair_quality_status:'ELIGIBLE',evidence:{change_id:'C0206',cohort:`${cfg.sl}_to_${cfg.dl}`,cohort_role:cfg.split==='TRAIN'?'historical training foreign-to-PL':'pre-test validation foreign-to-PL',used_for_fitting:cfg.split==='TRAIN',used_for_transform_scale:cfg.split==='TRAIN',source_minute_gate:450,destination_minute_gate:450,source_preferred_900:a.mins>=900,destination_preferred_900:b.mins>=900,single_record_each_season_required:true,same_understat_provider_both_sides:true,source_league:LEAGUE_NAME[a.league],goalkeepers_excluded:true,missing_data_is_not_zero:true,current_2026_27_target_outcomes_used:false,historical_forecasts_rewritten:false},research_only:true,model_effect_enabled:false});
  }
  const counts:Record<string,number>={};const positions:Record<string,number>={};for(const p of pairs){counts[p.source_competition]=(counts[p.source_competition]||0)+1;const k=`${p.source_competition}|${p.position_group}`;positions[k]=(positions[k]||0)+1}
  let inserted=0;if(!dryRun){for(const c of chunks(pairs)){const {data,error}=await sb.from('research_c0206_foreign_translation_pairs').upsert(c,{onConflict:'pair_key',ignoreDuplicates:true}).select('pair_key');if(error)throw error;inserted+=(data||[]).length}}
  return Response.json({ok:true,change_id:'C0206',cohort:cfg.split,dry_run:dryRun,source_year:cfg.sy,destination_year:cfg.dy,archive_rows:all.length,candidate_pairs:pairs.length,league_counts:counts,league_position_counts:positions,source_multirow_player_years_excluded:sourceMulti,destination_multirow_player_years_excluded:destMulti,sample:pairs.slice(0,20).map(p=>({player:p.player_name,source_league:p.source_competition,source_club:p.source_club,destination_club:p.destination_club,position:p.position_group,source_minutes:p.source_minutes,destination_minutes:p.destination_minutes,source_xg:p.source_xg,source_xa:p.source_xa,destination_xg:p.destination_xg,destination_xa:p.destination_xa})),inserted_or_returned:inserted,repository:REPO,repository_commit:COMMIT,file_blob_sha:BLOB,model_effect_enabled:false,historical_forecasts_rewritten:false});
}catch(e){return Response.json({ok:false,error:err(e)},{status:500})}});
